@bindable
extends Node2D
const Model = preload("res://examples/twoway/generated/Model.gd")
const Element = preload("../../../addons/estragon/runtime/composition/element.gd")
const Entry = preload("../../../addons/estragon/runtime/node/estragon_2d.gd")
const Box = preload("../../../addons/estragon/runtime/node/vbox.gd")
const Toggle = preload("../../../addons/estragon/runtime/node/toggle.gd")
const Text = preload("../../../addons/estragon/runtime/node/text.gd")
const Action = preload("../../../addons/estragon/runtime/node/button.gd")
const Row = preload("res://examples/twoway/generated/Row.gd")
var model: Model = Model.new()
var enabled: bool = false
var show_row: bool = true
var reverse: bool = false
var revision: int = 0
func build_view() -> Element:
    var rows: Array = [<Row key={1} name="First" model={self.model} />, <Row key={2} name="Second" model={self.model} />] if self.model != null and self.show_row else []
    if self.reverse: rows.reverse()
    return <Entry name="UI"><Box name="Panel" gap={8.0}>
        <Text name="Heading" text="Native two-way boolean input" />
        {<Toggle name="Edit" text="Model enabled" bind:value={self.model.enabled} /> if self.model != null else null}
        <Text name="Status" text={"Enabled" if self.model != null and self.model.enabled else "Disabled"} />
        <Toggle name="HostEdit" text="Host flag" bind:value={self.enabled} />
        <Text name="Revision" text={"Revision: %d" % self.revision} />
        {rows}
        <Action text="Replace model" pressed={replace_model} />
        <Action text="Show / hide rows" pressed={toggle_rows} />
        <Action name="Reverse" text="Reverse keys" pressed={reverse_rows} />
    </Box></Entry>
func replace_model() -> void:
    model = Model.new()
func toggle_rows() -> void:
    show_row = not show_row
func reverse_rows() -> void:
    reverse = not reverse
func _ready() -> void:
    if OS.get_environment("ESTRAGON_TWOWAY_PROOF")=="1": _proof.call_deferred()
func _proof() -> void:
    for index in range(8): await get_tree().process_frame
    var output := FileAccess.open("res://.godot/twoway-play.json",FileAccess.WRITE)
    output.store_string(JSON.stringify({"count":revision,"text":"Revision: %d" % revision}))
    output.close()
